const PRO_UNITS_DEFAULT=["斤","公斤","个","袋","打","盒","两","克","千克","瓶","箱","只","条","份","件","颗","根","把","扎","碗","盘","升","ml","L","kg","KG","g","mL","毫升","斤两"];
