function proUnits(){try{return [...new Set([...PRO_UNITS_DEFAULT,...JSON.parse(Exact.or(()=>(localStorage.getItem("restaurant_web_units")), ()=>("[]")))])];}catch(_){return [...PRO_UNITS_DEFAULT];}}
function proDateToolbar(id,label="选择日期"){return `<div class="pro-toolbar"><strong>${label}：</strong><button class="pro-button" data-date-shift="${id}" data-shift="-1">◀ 前一天</button><input id="${id}" type="date"><button class="pro-button" data-date-shift="${id}" data-shift="1">后一天 ▶</button><button class="pro-button" data-date-today="${id}">今天</button><span class="grow"></span></div>`;}
function proUnitOptions(value=""){return [...new Set(["",...proUnits(),value].filter(item=>Exact.and(()=>(Exact.sneq(item, undefined)), ()=>(Exact.sneq(item, null)))))].map(item=>`<option ${(Exact.truth(Exact.seq(item, value)) ? "selected" : "")}>${escapeHtml(item)}</option>`).join("");}
function proShiftDate(id,amount){const node=$(id);if(Exact.truth(Exact.not(node?.value)))return;const date=parseDate(node.value);date.setDate(Exact.add(date.getDate(), amount));node.value=isoDate(date);node.dispatchEvent(new Event("change"));}
function proInstallDateButtons(root=document){root.querySelectorAll("[data-date-shift]").forEach(button=>button.addEventListener("click",()=>proShiftDate(button.dataset.dateShift,Exact.toNumber(button.dataset.shift))));root.querySelectorAll("[data-date-today]").forEach(button=>button.addEventListener("click",()=>{const node=$(button.dataset.dateToday);node.value=isoDate(new Date());node.dispatchEvent(new Event("change"));}));}

