function captureWebEditorDraft(target){
  if(Exact.truth(Exact.not(target?.closest)))return false;
  if(Exact.truth(target.closest("#pageLedger"))){
    if(Exact.truth(PRO_FIXED_DRAFT_FIELDS.includes(target.id)))captureFixedDraft();
    else captureLedgerDraft();
    return true;
  }
  else if(Exact.truth(target.closest("#pageDishes"))){captureDishesDraft();return true;}
  else if(Exact.truth(target.closest("#pageFood"))){captureDetailDraft("food");return true;}
  else if(Exact.truth(target.closest("#pageSpice"))){captureDetailDraft("spice");return true;}
  else if(Exact.truth(target.closest("#pageInventory"))){captureInventoryDraft();return true;}
  else if(Exact.truth(target.closest("#pageUsers"))){captureUsersDraft();return true;}
  return false;
}
